// =========================
// Batch helpers
// =========================
const batchUpdateApi = async (endpoint, items, options = {}) => {
  const {
    batchSize = 100,
    operation = "update",
    headers = {}
  } = options;
  const baseUrl = `${window.siteUrl}/wp-json/wc/v3/`;
  const defaultHeaders = {
    "Content-Type": "application/json",
    "X-WP-Nonce": window.rest,
    ...headers
  };
  const batches = [];
  for (let i = 0; i < items.length; i += batchSize) {
    batches.push(items.slice(i, i + batchSize));
  }
  const results = [];
  const errors = [];
  try {
    for (const batch of batches) {
      const payload = {
        [operation]: batch
      };
      const response = await axios__WEBPACK_IMPORTED_MODULE_0__["default"].post(baseUrl + endpoint, payload, {
        headers: defaultHeaders
      });
      if (response.data[operation]) {
        results.push(...response.data[operation]);
        const batchErrors = response.data[operation].filter(item => item?.error);
        if (batchErrors.length > 0) {
          errors.push(...batchErrors);
        }
      }
    }
    return {
      success: true,
      results,
      errors,
      totalProcessed: results.length,
      totalErrors: errors.length
    };
  } catch (error) {
    console.error("Batch update failed:", error);
    return {
      success: false,
      error: error?.response?.data?.message || error.message || "Unknown error occurred",
      results: [],
      errors: []
    };
  }
};
